with deduped as (select * from (select *, row_number() over (partition by country, device order by started_at asc nulls first, id asc) as rn from sessions) ranked where rn = 1) select date_trunc('week', started_at) as week_start, max(started_at) as last_seen, count_if(device = 'tablet') as tablet_events, count(*) filter (where device = 'mobile') as mobile_rows, min(started_at) as first_started_at, count(distinct browser) as distinct_browsers, count(*) as num_rows from deduped group by week_start order by distinct_browsers desc nulls first;
